  "cdm.product.common.schedule.FxLinkedNotionalSchedule" : [ {
    "name" : "varyingNotionalCurrency",
    "type" : "string",
    "description" : "The currency of the varying notional amount, i.e. the notional amount being determined periodically based on observation of a spot currency exchange rate. The list of valid currencies is not presently positioned as an enumeration as part of the CDM because that scope is limited to the values specified by ISDA and FpML. As a result, implementers have to make reference to the relevant standard, such as the ISO 4217 standard for currency codes.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "1"
    },
    "metaField" : true
  }, {
    "name" : "varyingNotionalFixingDates",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "RelativeDateOffset",
      "namespace" : "cdm.base.datetime",
      "description" : "A class defining a date (referred to as the derived date) as a relative offset from another date (referred to as the anchor date). If the anchor date is itself an adjustable date then the offset is assumed to be calculated from the adjusted anchor date. A number of different scenarios can be supported, namely; 1) the derived date may simply be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date; 2) the unadjusted derived date may be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date with the resulting unadjusted derived date subject to adjustment in accordance with a specified business day convention, i.e. the derived date must fall on a good business day; 3) the derived date may be a number of business days preceding or following the anchor date. Note that the businessDayConvention specifies any required adjustment to the unadjusted derived date. A negative or positive value in the periodMultiplier indicates whether the unadjusted derived precedes or follows the anchor date. The businessDayConvention should contain a value NONE if the day type element contains a value of Business (since specifying a negative or positive business days offset would already guarantee that the derived date would fall on a good business day in the specified business centers)."
    },
    "description" : "The dates on which spot currency exchange rates are observed for purposes of determining the varying notional currency amount that will apply to a calculation period.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "1"
    },
    "metaField" : false
  }, {
    "name" : "fxSpotRateSource",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "FxSpotRateSource",
      "namespace" : "cdm.observable.asset",
      "description" : "A class defining the rate source and fixing time for an FX rate."
    },
    "description" : "The information source and time at which the spot currency exchange rate will be observed.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "1"
    },
    "metaField" : false
  }, {
    "name" : "fixingTime",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "BusinessCenterTime",
      "namespace" : "cdm.base.datetime",
      "description" : "A class for defining a time with respect to a business day calendar location. For example, 11:00:00 GBLO."
    },
    "description" : "The time at which the spot currency exchange rate will be observed. It is specified as a time in a business day calendar location, e.g. 11:00am London time.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  }, {
    "name" : "varyingNotionalInterimExchangePaymentDates",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "RelativeDateOffset",
      "namespace" : "cdm.base.datetime",
      "description" : "A class defining a date (referred to as the derived date) as a relative offset from another date (referred to as the anchor date). If the anchor date is itself an adjustable date then the offset is assumed to be calculated from the adjusted anchor date. A number of different scenarios can be supported, namely; 1) the derived date may simply be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date; 2) the unadjusted derived date may be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date with the resulting unadjusted derived date subject to adjustment in accordance with a specified business day convention, i.e. the derived date must fall on a good business day; 3) the derived date may be a number of business days preceding or following the anchor date. Note that the businessDayConvention specifies any required adjustment to the unadjusted derived date. A negative or positive value in the periodMultiplier indicates whether the unadjusted derived precedes or follows the anchor date. The businessDayConvention should contain a value NONE if the day type element contains a value of Business (since specifying a negative or positive business days offset would already guarantee that the derived date would fall on a good business day in the specified business centers)."
    },
    "description" : "The dates on which interim exchanges of notional are paid. Interim exchanges will arise as a result of changes in the spot currency exchange amount or changes in the constant notional schedule (e.g. amortisation).",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "1"
    },
    "metaField" : false
  } ],
