  "cdm.product.common.settlement.ValuationDate" : [ {
    "name" : "singleValuationDate",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "SingleValuationDate",
      "namespace" : "cdm.observable.asset",
      "description" : "A class to specify the number of business days after satisfaction of all conditions to settlement."
    },
    "description" : "Where single valuation date is specified as being applicable for cash settlement, this element specifies the number of business days after satisfaction of all conditions to settlement when such valuation date occurs. ISDA 2003 Term: Single Valuation Date.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  }, {
    "name" : "multipleValuationDates",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "MultipleValuationDates",
      "namespace" : "cdm.observable.asset"
    },
    "description" : "Where multiple valuation dates are specified as being applicable for cash settlement, this element specifies (a) the number of applicable valuation dates, and (b) the number of business days after satisfaction of all conditions to settlement when the first such valuation date occurs, and (c) the number of business days thereafter of each successive valuation date. ISDA 2003 Term: Multiple Valuation Dates.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  }, {
    "name" : "valuationDate",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "RelativeDateOffset",
      "namespace" : "cdm.base.datetime",
      "description" : "A class defining a date (referred to as the derived date) as a relative offset from another date (referred to as the anchor date). If the anchor date is itself an adjustable date then the offset is assumed to be calculated from the adjusted anchor date. A number of different scenarios can be supported, namely; 1) the derived date may simply be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date; 2) the unadjusted derived date may be a number of calendar periods (days, weeks, months or years) preceding or following the anchor date with the resulting unadjusted derived date subject to adjustment in accordance with a specified business day convention, i.e. the derived date must fall on a good business day; 3) the derived date may be a number of business days preceding or following the anchor date. Note that the businessDayConvention specifies any required adjustment to the unadjusted derived date. A negative or positive value in the periodMultiplier indicates whether the unadjusted derived precedes or follows the anchor date. The businessDayConvention should contain a value NONE if the day type element contains a value of Business (since specifying a negative or positive business days offset would already guarantee that the derived date would fall on a good business day in the specified business centers)."
    },
    "description" : "The date on which the cash settlement amount will be determined according to the cash settlement method if the parties have not otherwise been able to agree the cash settlement amount. This attribute was formerly part of 'OptionCashSettlement', which is now being harmonised into a common 'CashSettlementTerms' that includes a 'ValuationDate'.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  }, {
    "name" : "fxFixingDate",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "FxFixingDate",
      "namespace" : "cdm.product.common.settlement",
      "description" : "Extends the Offset structure to specify an FX fixing date as an offset to dates specified somewhere else in the document."
    },
    "description" : "The date on which the currency rate will be determined for the purpose of specifying the amount in deliverable currency. This attribute was formerly part of 'NonDeliverableSettlement', which is now being harmonised into a common 'CashSettlementTerms' that includes a 'ValuationDate'.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  }, {
    "name" : "fxFixingSchedule",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "AdjustableDates",
      "namespace" : "cdm.base.datetime",
      "description" : "A class for defining a series of dates that shall be subject to adjustment if they would otherwise fall on a day that is not a business day in the specified business centers, together with the convention for adjusting the dates."
    },
    "description" : "The date, when expressed as a schedule of date(s), on which the currency rate will be determined for the purpose of specifying the amount in deliverable currency. This attribute was formerly part of 'NonDeliverableSettlement', which is now being harmonised into a common 'CashSettlementTerms' that includes a 'ValuationDate'.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "0"
    },
    "metaField" : false
  } ],
