  "cdm.event.common.QuantityChangeInstruction" : [ {
    "name" : "change",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "PriceQuantity",
      "namespace" : "cdm.observable.asset",
      "description" : "Defines a settlement as an exchange between two parties of a specified quantity of an asset (the quantity) against a specified quantity of another asset (the price). The settlement is optional and can be either cash or physical. The quantity can additionally be specified in terms of one or more currency amounts. In the case of non-cash products, the settlement of the price/quantity would not be specified here and instead would be delegated to the product mechanics, as parameterised by the price/quantity values."
    },
    "description" : "Quantity by which the trade is being increased, decreased or replaced, and the price at which such quantity change is agreed. The quantity change should always be specified as a positive number, with the direction (increase/decrease/replacement) being specified by the direction enumeration. A fee can also be associated to the quantity change by specifying a Price component of type CashPrice, including the corresponding settlement date and direction.",
    "cardinality" : {
      "upperBound" : "*",
      "lowerBound" : "1"
    },
    "metaField" : false
  }, {
    "name" : "direction",
    "type" : {
      "typeCategory" : "EnumType",
      "name" : "QuantityChangeDirectionEnum",
      "values" : [ {
        "name" : "INCREASE",
        "displayName" : "Increase",
        "description" : "When the quantity should go up by the specified amount."
      }, {
        "name" : "DECREASE",
        "displayName" : "Decrease",
        "description" : "When the quantity should go down by the specified amount."
      }, {
        "name" : "REPLACE",
        "displayName" : "Replace",
        "description" : "When the quantity should be replaced by the specified amount."
      } ]
    },
    "description" : "Direction of the quantity change specified as either an increase, decrease or replacement.",
    "cardinality" : {
      "upperBound" : "1",
      "lowerBound" : "1"
    },
    "metaField" : false
  }, {
    "name" : "lotIdentifier",
    "type" : {
      "typeCategory" : "StructuredType",
      "name" : "Identifier",
      "namespace" : "cdm.base.staticdata.identifier",
      "description" : "A class to specify a generic identifier, applicable to CDM artefacts such as executions, contracts, lifecycle events and legal documents. An issuer can be associated with the actual identifier value as a way to properly qualify it."
    },
    "description" : "Identifier for the new lot (in case of increase) or for the existing lot to be changed(in case of decrease or replacement). This optional attribute is mandatory in case of a decrease or replacement if the initial trade state contains multiple trade lots.",
    "cardinality" : {
      "upperBound" : "*",
      "lowerBound" : "0"
    },
    "metaField" : false
  } ],
